import { GoogleGenAI } from "@google/genai";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: (process.env.API_KEY as string) });
  }

  async getEnglishPracticeResponse(userInput: string, chatHistory: any[] = []) {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userInput,
        config: {
          systemInstruction: `You are a helpful and encouraging English Practice Bot for students learning English with Masud Sir. 
          Your goals are:
          1. Correct the user's grammar if they make mistakes, but be polite.
          2. Suggest better vocabulary words.
          3. Keep the conversation engaging to encourage more speaking/typing.
          4. If the user asks about specific English concepts, explain them simply.
          5. Always encourage them to join Masud Sir's full courses.`,
        }
      });
      return response.text;
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "I'm sorry, I'm having trouble connecting right now. Let's practice again in a moment!";
    }
  }

  async checkPronunciation(transcript: string) {
    // This would be a more complex implementation in a real app
    // For now, we use Gemini to evaluate text fluency
    const prompt = `Evaluate the following transcript of a student speaking English. Give a score from 1-10 on fluency and suggest 3 improvements: "${transcript}"`;
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  }
}

export const geminiService = new GeminiService();

